  {
    "Name": "FolderManagementGrid",
    "Content": "async function (vars) {
    var g = new GridWidget(vars.element);
    g.groupable = false;
    g.config.endpoint = "DocumentManagement/File";
    g.config.odataAppend = "?$filter=FolderId eq " + vars.folder.Id;

    var functionsCol =
        "<a name='download'  download='#=Name#' target='_blank' href='" + session.apiRoot + "DMS/#=Path#?t=" + session.token + "'><span class='k-icon k-i-download'></span>[resource_displayname[Download]]</a>";
    var link = session.apiRoot + "DMS/" + vars.folder.Path + "?t=" + session.token;
    var toolbar = "<a name='download' target='_blank' href='" + link + "'></span>[resource_displayname[Download]]</a>";
    if (!readOnly) {
        functionsCol += "<a name='save'><span class='k-icon k-i-check'></span>[resource_displayname[Save]]</a>" +
            "<a name='deleteFile' style='margin-right: 50px;'><span class='k-icon k-i-delete'></span>[resource_displayname[Delete]]</a>";
        toolbar += "<div class='drop'><input name='dropTarget' type='file' multiple></input></div>";
    }
    g.toolbar = toolbar;
    g.columns = [
        // Icons for this pulled from ...
        // https://github.com/dmhendricks/file-icon-vectors
        { title: '', width: 30, template: '<span class="icon fiv-sqo fiv-icon-#:Name.split(".")[Name.split(".").length-1]#"></span>' },
        { field: "Name", title: "[resource_shortdisplayname[Name]]" },
        { field: 'Size', width: 80, title: "[resource_shortdisplayname[Size]]" },
        { width: 200, field: 'CreatedBy', title: "[resource_shortdisplayname[CreatedBy]]", editable: false, width: 120 },
        { width: 130, field: 'CreatedOn', title: "[resource_shortdisplayname[CreatedOn]]", editable: false, format: "{0:" + type.dateFormat + " hh:mm:ss}" },

        { width: 280, template: functionsCol }
    ];
    variables.FolderManagementGrid = g;
}",
